import {PRAYERS,STATES,WAITING_STATE,DAILY_MEDAL_TARGETS,dailyStats,eligiblePrayerKeys,dateInTimezone,localDate,shiftDate,achievementRange,emptyDay} from './domain.js?v=20261001-city-times';

const root=document.querySelector('#app');
const state={user:null,date:validDate(new URLSearchParams(location.search).get('date'))||localDate(),day:null,view:'day',busy:false,error:'',authMode:'login',stats:null,history:[],cities:[],citiesLoaded:false,achievementPeriod:'last30',achievementRequestEpoch:0,loading:true,sessionEpoch:0,dataEpoch:0};
Object.assign(state,{selectedChild:null,selectionEpoch:0,supervisors:[],children:[],invites:[],managementLoaded:false,managementRequestEpoch:0,operationEpoch:0,managementError:'',inviteToken:'',invitePreview:null,inviteError:'',acceptKey:null,shareLink:'',shareInviteId:null});
Object.assign(state,{reportDate:null,reportRows:[],reportOffset:0,reportTotal:0,reportLoading:false,reportError:'',reportEpoch:0,reportReturn:false});
const INVITE_STORAGE='prayer.pending-invite';
// Auth responses change the HttpOnly cookie even if their UI response is ignored.
// Serialize them independently of cancellable invitation/diary operations.
let authRequestPending=false;
function saveInvite(token){state.inviteToken=token;try{sessionStorage.removeItem(INVITE_STORAGE+'.accept');if(token)sessionStorage.setItem(INVITE_STORAGE,token);else sessionStorage.removeItem(INVITE_STORAGE);}catch{}}
function captureInvite(){const fragment=location.hash.slice(1);if(fragment.startsWith('invite=')){let token='';try{token=new URLSearchParams(fragment).get('invite')||'';}catch{}saveInvite(/^[A-Za-z0-9_-]{32,128}$/.test(token)?token:'');state.invitePreview=null;state.acceptKey=null;state.operationEpoch++;state.busy=false;history.replaceState(null,'',location.pathname+location.search);return true;}return false;}
if(!captureInvite()){try{state.inviteToken=sessionStorage.getItem(INVITE_STORAGE)||'';}catch{}}
const contextUser=()=>state.selectedChild||state.user;
const contextStamp=()=>`${state.sessionEpoch}:${state.user?.id}:${state.selectionEpoch}:${state.selectedChild?.id||''}`;
const sameContext=stamp=>stamp===contextStamp();
const readPath=path=>state.selectedChild?`/supervisor/children/${encodeURIComponent(state.selectedChild.id)}${path}`:path;
function clearData(){state.selectionEpoch++;state.dataEpoch++;state.day=null;state.stats=null;state.history=[];state.achievementRequestEpoch++;}
function resetAccount(){state.reportEpoch++;state.reportDate=null;state.reportRows=[];state.reportOffset=0;state.reportTotal=0;state.reportLoading=false;state.reportError='';state.reportReturn=false;state.operationEpoch++;state.selectedChild=null;clearData();state.supervisors=[];state.children=[];state.invites=[];state.managementLoaded=false;state.managementRequestEpoch++;state.managementError='';state.shareLink='';state.shareInviteId=null;state.invitePreview=null;state.inviteError='';state.acceptKey=null;state.busy=false;}
function requestKey(){if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();if(globalThis.crypto?.getRandomValues){const bytes=new Uint8Array(24);globalThis.crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;}
const number=value=>new Intl.NumberFormat('ar',{numberingSystem:'arab'}).format(value);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const thumbs='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M11 27H6a2 2 0 0 1-2-2V14a2 2 0 0 1 2-2h5m0 15h12c2 0 3-1 3.4-3l2-10c.4-2-1-4-3-4h-7l1-5c.5-3-3-4-4-1l-5 8v15Z" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg>';
const icons={day:'☀',achievements:'★',account:'●',report:'▦'};
const today=()=>dateInTimezone(contextUser()?.timezone);
const scheduleKeys=()=>state.day?eligiblePrayerKeys(state.day):[];
const prayerEnabled=key=>{const keys=scheduleKeys();return Array.isArray(keys)&&keys.includes(key);};
const prayerTime=key=>{const schedule=state.day?.schedule;if(!schedule?.available||!schedule.times?.[key])return null;try{return new Intl.DateTimeFormat('ar-SA',{timeZone:schedule.timezone||contextUser()?.timezone,hour:'numeric',minute:'2-digit'}).format(new Date(schedule.times[key]));}catch{return null;}};
const scheduleUnavailable=()=>state.day?.schedule?.available===false;

function validDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')&&!Number.isNaN(new Date(value+'T12:00:00').getTime())&&localDate(new Date(value+'T12:00:00'))===value?value:null;}
const ACHIEVEMENT_PERIODS=Object.freeze({week:'هذا الأسبوع',month:'هذا الشهر',last30:'آخر ٣٠ يومًا'});
function achievementPeriodDetails(period=state.achievementPeriod){
 const {from,to}=achievementRange(period,today());
 const format=value=>new Intl.DateTimeFormat('ar-SA',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${value}T12:00:00`));
 return {from,to,label:ACHIEVEMENT_PERIODS[period],dateLabel:`${format(from)} – ${format(to)}`};
}
function announce(message,error=false){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.toggle('is-error',error);toast.hidden=false;clearTimeout(announce.timer);announce.timer=setTimeout(()=>toast.hidden=true,4500);}
async function api(path,options={}){
 const response=await fetch('/api/v1'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
 let result;try{result=await response.json();}catch{result={detail:'تعذّر الاتصال بالدفتر. جرّب مرة أخرى'};}
 if(!response.ok){const error=new Error(typeof result.detail==='string'?result.detail:'تحقّق من البيانات وحاول مرة أخرى');error.status=response.status;throw error;}return result;
}
function hero(){const headerDate=state.view==='report'?(state.reportDate||shiftDate(reportToday(),-1)):state.date;return `<header class="hero"><div class="hero-scenery" aria-hidden="true"></div><div class="hero-inner"><div class="hello"><img class="avatar" src="/assets/child-home.png" alt="" /><div><span class="eyebrow">خطوات صغيرة، فرحة كبيرة</span><h1>${state.user?'مرحباً يا بطل!':'أهلاً يا بطل!'}</h1><p>${state.user?`دفتر ${esc(state.user.alias)} الصغير`:'كل يوم فرصة لخطوة جميلة'}</p></div></div>${state.user?`<div class="date-card"><span class="calendar-icon" aria-hidden="true">▦</span><div><span class="date-eyebrow">${headerDate===(state.view==='report'?reportToday():today())?'يومك الجميل':'من دفتر أيامك'}</span><strong>${esc(new Intl.DateTimeFormat('ar',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(headerDate+'T12:00:00')))}</strong>${contextUser().city_name?`<small>${esc(contextUser().city_name)}</small>`:''}</div></div>`:'<div class="cloud-note"><span aria-hidden="true">✦</span> دفتر بسيط، وفرحة بكل خطوة</div>'}</div></header>`;}
function navbar(){return `<nav class="bottom-nav" aria-label="التنقل الرئيسي">${[['day','صلاتي اليوم'],['achievements','إنجازاتي'],['account','حسابي'],...(state.user?.can_supervise?[['report','متابعة الطلاب']]:[])].map(([view,label])=>`<button type="button" class="nav-link ${state.view===view?'active':''}" data-action="view" data-view="${view}" ${state.view===view?'aria-current="page"':''}><span aria-hidden="true">${icons[view]}</span>${label}</button>`).join('')}</nav>`;}
function auth(){const signup=state.authMode==='register';return `${hero()}<main id="main" class="auth-layout"><section class="auth-intro"><span class="small-chip">دفترك الخاص</span><h2>صلاتي اليوم</h2><p class="intro-text">خمس صلوات، خطوة بخطوة</p><div class="character-trio" aria-hidden="true"><img src="/assets/child-waiting.svg"/><img src="/assets/child-home.png"/><img src="/assets/child-mosque.png"/></div><div class="intro-points"><p><span>✦</span> شخصيتك تتغيّر بلمسة واحدة</p><p><span>✦</span> الفرض والسنن كلٌّ في مكانه</p><p><span>✦</span> أيامك محفوظة في دفتر خاص</p></div></section><section class="auth-card" aria-labelledby="auth-title"><div class="auth-tabs"><button class="${!signup?'selected':''}" data-action="auth-mode" data-mode="login" type="button">دخول</button><button class="${signup?'selected':''}" data-action="auth-mode" data-mode="register" type="button">حساب جديد</button></div><h2 id="auth-title">${signup?'لنبدأ دفترًا جديدًا':'نورت دفتر يومك'}</h2><p class="muted">${signup?'اختر اسمًا مستعارًا وكلمة مرور لحفظ خطواتك':'ادخل باسمك المستعار لتكمل خطواتك'}</p>${state.inviteToken?'<p class="invite-notice">لديك دعوة إشراف. ادخل أو أنشئ حسابًا لعرضها وتأكيدها، أو <button type="button" class="text-button" data-action="cancel-invite">إلغاء الدعوة</button></p>':''}<form id="auth-form">${signup?'<label for="account-type">نوع الحساب</label><select id="account-type" name="account_type"><option value="child">حساب طفل</option><option value="supervisor">حساب مشرف</option></select>':''}<label for="alias">الاسم المستعار</label><input id="alias" name="alias" autocomplete="username" minlength="3" maxlength="24" required placeholder="مثل: بطل_النور" dir="auto"/><label for="password">كلمة المرور</label><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" maxlength="128" required placeholder="٨ أحرف على الأقل"/><p id="auth-error" class="form-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</p><button type="submit" class="primary-button" ${state.busy?'disabled':''}>${state.busy?'لحظة صغيرة…':signup?'ابدأ رحلتك ✦':'افتح دفتري ←'}</button></form><p class="privacy-note"><span aria-hidden="true">♢</span> استخدم اسمًا مستعارًا فقط. بعد الدخول تختار مدينتك لحساب أوقات الصلاة، من دون إذن للموقع الدقيق</p><p class="guardian-note">هذه نسخة تجريبية. للحسابات التجريبية فقط بإشراف وليّ الأمر</p></section></main><footer class="auth-footer">صنعنا مساحة هادئة للمحاولة والتعلّم، بلا مقارنة أو ضغط</footer>`;}
function sunnahCell(prayer,side){const key=prayer[side];if(!key)return `<div class="sunnah-cell empty" aria-label="لا توجد سنة ${side==='before'?'قبلية':'بعدية'} معروضة لهذه الصلاة"><span aria-hidden="true">—</span></div>`;
 const isDhuhr=key==='dhuhr_before';const count=state.day.sunnah[key];const locked=!prayerEnabled(prayer.key);const blocks=isDhuhr?state.day.dhuhr_before_blocks||[count>=2,count===4]:[count===2];
 return `<div class="sunnah-cell ${locked?'locked':''}"><span class="sunnah-name">سنة ${side==='before'?'قبلية':'بعدية'}</span><div class="thumb-blocks">${blocks.map((active,index)=>`<button type="button" class="thumb-button ${active?'checked':''}" data-action="sunnah" data-key="${key}" ${isDhuhr?`data-block="${index}"`:''} aria-pressed="${active}" aria-label="${prayer.name}: ركعتان ${side==='before'?'قبلية':'بعدية'}${isDhuhr?`، المجموعة ${number(index+1)}`:''}. ${locked?'تتاح عند دخول وقت الصلاة':active?'حصلت على ميدالية فضية':'أكملها لتحصل على ميدالية فضية'}" ${state.busy||locked||state.selectedChild?'disabled':''}>${thumbs}<span>٢ ركعة</span><em class="control-reward">🥈 ${active?'+١':'١'}</em>${active?'<b class="tiny-check" aria-hidden="true">✓</b>':''}</button>`).join('')}</div>${isDhuhr?`<small class="block-total">${number(count)} من ٤ ركعات</small>`:''}</div>`;
}
function row(prayer){const prayerState=state.day.prayers[prayer.key];const locked=!prayerEnabled(prayer.key);const status=locked?WAITING_STATE:STATES[prayerState];const gold=prayerState===1?1:prayerState===2?27:0;const time=prayerTime(prayer.key);const timeCopy=scheduleUnavailable()?'الوقت غير متاح':time?`وقت الصلاة ${time}`:state.day.schedule==null?'الوقت حسب مدينتك':state.date>today()?'موعد قادم':'الوقت غير متاح';return `<article class="prayer-row ${prayer.theme} ${locked?'locked':''}" aria-labelledby="title-${prayer.key}"><div class="prayer-banner"><img src="/assets/${prayer.key}.svg" alt=""/><div><h3 id="title-${prayer.key}">${prayer.name}</h3><p>${prayer.caption}</p><time>${esc(timeCopy)}</time></div></div>${sunnahCell(prayer,'before')}<div class="fard-cell"><button type="button" class="character-button ${status.className}" data-action="prayer" data-key="${prayer.key}" aria-label="${prayer.name}: ${status.label}. ${state.selectedChild?'للقراءة فقط':locked?timeCopy:`${gold?`المكافأة ${number(gold)} ميدالية ذهبية`:'لا توجد ميداليات بعد'}. اضغط للتبديل إلى ${status.next}`}" ${state.busy||locked||state.selectedChild?'disabled':''}><img src="/assets/${status.image}" alt=""/><span class="state-copy"><strong>${status.label}</strong><em class="prayer-reward">🥇 ${number(gold)}</em><small>${state.selectedChild?'للقراءة فقط':locked?timeCopy:'اضغط على الشخصية للتغيير <span aria-hidden="true">↻</span>'}</small></span></button></div>${sunnahCell(prayer,'after')}</article>`;}
function editableDailyBoard(s){const witrLocked=!prayerEnabled('isha');return `<div class="board-heading" aria-hidden="true"><span>الصلاة</span><span>السنة القبلية</span><span>الفرض</span><span>السنة البعدية</span></div><section class="prayer-board" aria-label="الصلوات الخمس">${PRAYERS.map(row).join('')}</section><section class="witr-card ${witrLocked?'locked':''}" aria-labelledby="witr-title"><div class="witr-heading"><span class="moon" aria-hidden="true">☾</span><div><h3 id="witr-title">الوتر <span>سنة بعد العشاء</span></h3><p>${witrLocked?'يتاح عند دخول وقت العشاء':'له خطوة مستقلة في دفتر السنن'}</p></div></div><button type="button" class="witr-button ${s.witr?'checked':''}" data-action="witr" aria-pressed="${Boolean(s.witr)}" aria-label="${witrLocked?'الوتر متاح بعد دخول وقت العشاء':s.witr?'صليت الوتر وحصلت على ميدالية فضية':'سجّل صلاة الوتر لتحصل على ميدالية فضية'}" ${state.busy||witrLocked||state.selectedChild?'disabled':''}><span class="toggle-check" aria-hidden="true">${s.witr?'✓':'+'}</span>${state.selectedChild?(s.witr?'الوتر مكتمل · 🥈 ١':'الوتر غير مسجّل'):s.witr?'صلّيت الوتر · 🥈 +١':'سجّل الوتر · 🥈 ١'}</button></section>`;}
function daily(){
 if(!state.day)return `<main id="main" class="page-main"><p class="loading">نفتح صفحة يومك…</p></main>`;
 const s=dailyStats(state.day);
 const unavailable=s.percent==null;
 const goldTarget=s.gold_target??(state.day.schedule==null?DAILY_MEDAL_TARGETS.gold:null);
 const silverTarget=s.silver_target??(state.day.schedule==null?DAILY_MEDAL_TARGETS.silver:null);
 const value=v=>v==null?'—':number(v);
 return `<main id="main" class="page-main"><div class="title-and-date"><div class="page-title"><span class="small-chip">دفتر يومك</span><h2>صلاتي اليوم <span aria-hidden="true">✦</span></h2><p>${contextUser().city_name?`مواقيت ${esc(contextUser().city_name)}، وتتفتح كل خطوة عند دخول وقتها`:'اختر مدينتك من حسابي لعرض مواقيت الصلاة'}</p></div><div class="date-controls"><button data-action="date-shift" data-days="-1" type="button" aria-label="اليوم السابق" ${state.busy?'disabled':''}>→</button><label class="date-input-label"><span class="sr-only">اختر يومًا</span><input type="date" id="day-date" value="${state.date}" aria-label="اختر يومًا" ${state.busy?'disabled':''}/></label><button data-action="date-shift" data-days="1" type="button" aria-label="اليوم التالي" ${state.busy?'disabled':''}>←</button><button class="today-button" data-action="today" type="button" ${state.date===today()?'disabled':''}>اليوم</button></div></div>${scheduleUnavailable()?`<p class="schedule-alert" role="status">تعذّر جلب مواقيت الصلاة لهذا اليوم. سنعيد المحاولة تلقائيًا، ولن نحسب نسبة غير دقيقة.</p>`:''}${state.selectedChild?compactPrayerTable([{day:state.day,label:`<span>${esc(contextUser().alias)}</span><small>${esc(reportDateLabel(state.date))}</small>`}],{label:'الطالب / اليوم',caption:`سجل ${contextUser().alias} — ${reportDateLabel(state.date)}`,region:'سجل يوم الطالب'}):editableDailyBoard(s)}<section class="reward-totals" aria-label="ميداليات اليوم"><article class="reward-total gold"><span aria-hidden="true">🥇</span><div><small>ذهبيات اليوم</small><strong>${value(s.gold_medals)} <em>/ ${value(goldTarget)}</em></strong><p>البيت ١ · المسجد ٢٧</p></div></article><article class="reward-total silver"><span aria-hidden="true">🥈</span><div><small>فضيات اليوم</small><strong>${value(s.silver_medals)} <em>/ ${value(silverTarget)}</em></strong><p>الهدف يتدرّج مع الصلوات التي دخل وقتها</p></div></article></section><section class="daily-summary" aria-label="إحصائيات اليوم"><div class="summary-card progress-card ${unavailable?'unavailable':''}"><div class="summary-top"><span class="summary-symbol" aria-hidden="true">▥</span><h3>خطواتك اليوم</h3><span class="percentage">${unavailable?'غير متاح':`${number(s.percent)}٪`}</span></div>${unavailable?'<p class="completed-text">تعذّر حساب التقدّم حتى تتوفر المواقيت</p>':`<div class="progress-track" role="progressbar" aria-label="إنجاز الفرائض المتاحة اليوم" aria-valuenow="${s.completed}" aria-valuemin="0" aria-valuemax="${s.total}"><span style="width:${s.percent}%"></span></div><p class="completed-text" aria-live="polite"><strong>${number(s.completed)} من ${number(s.total)}</strong> صلوات دخل وقتها</p><div class="places"><span><b>${number(s.home)}</b> في البيت</span><span><b>${number(s.mosque)}</b> في المسجد</span></div>`}</div><div class="summary-card sunnah-summary"><span class="summary-symbol" aria-hidden="true">✿</span><div><h3>خطوات السنن</h3><strong>${value(s.sunnah_rakahs)} <span>ركعات مسجّلة</span></strong><p>الوتر: ${s.witr==null?'غير متاح':s.witr?'مكتمل ✓':'لم يسجّل بعد'}</p><small>السنن مستقلة عن نسبة الفرائض</small></div></div><div class="summary-card encouragement"><span class="trophy" aria-hidden="true">🏆</span><div><h3>${s.total>0&&s.completed===s.total?'أكملت خطواتك المتاحة!':'كل خطوة تستحق فرحة!'}</h3><p>${s.total>0&&s.completed===s.total?'سجّلت كل الصلوات التي دخل وقتها':'خذ وقتك، وأكمل بطريقتك'}</p><button type="button" class="text-button" data-action="view" data-view="achievements">شاهد إنجازاتك ←</button></div></div></section><p class="saved-note"><span aria-hidden="true">✓</span> ${state.selectedChild?'دفتر الطفل للقراءة فقط':state.busy?'نحفظ خطوتك…':'خطواتك محفوظة في حسابك'} <span>•</span> الميداليات محسوبة من السجل الحالي</p></main>`;
}
function achievements(){
 const range=achievementPeriodDetails();
 const controls=`<section class="period-picker" aria-labelledby="period-title"><div><h3 id="period-title">الفترة</h3><p aria-live="polite">${esc(range.dateLabel)}</p></div><div class="period-buttons" role="group" aria-label="اختر فترة الإنجازات">${Object.entries(ACHIEVEMENT_PERIODS).map(([period,label])=>`<button type="button" data-action="achievement-period" data-period="${period}" aria-pressed="${state.achievementPeriod===period}" class="${state.achievementPeriod===period?'selected':''}">${label}</button>`).join('')}</div></section>`;
 if(!state.stats)return `<main id="main" class="page-main achievement-page"><div class="page-title"><span class="small-chip">خطوات تستحق الفرح</span><h2>إنجازاتي <span aria-hidden="true">★</span></h2><p>اختر فترة لترى ملخصها وميدالياتها وإنجازاتها وأيامها معًا</p></div>${controls}<p class="loading" role="status">نجمع خطواتك الجميلة…</p></main>`;
 const s=state.stats;
 const recordedDays=Number(s.recorded_days)||0;
 const goldTarget=Object.hasOwn(s,'gold_target')?s.gold_target:recordedDays*DAILY_MEDAL_TARGETS.gold;
 const silverTarget=Object.hasOwn(s,'silver_target')?s.silver_target:recordedDays*DAILY_MEDAL_TARGETS.silver;
 const prayerTarget=Object.hasOwn(s,'total')?s.total:recordedDays*PRAYERS.length;
 const value=v=>v==null?'—':number(v);
 return `<main id="main" class="page-main achievement-page"><div class="page-title"><span class="small-chip">خطوات تستحق الفرح</span><h2>إنجازاتي <span aria-hidden="true">★</span></h2><p>ملخص ${range.label} من الأيام المحفوظة</p></div>${controls}<section class="totals-grid" aria-label="إجمالي ${range.label}"><div class="medal-total gold"><span>الميداليات الذهبية</span><strong aria-label="الميداليات الذهبية: ${value(s.gold_medals)} من ${value(goldTarget)}">🥇 ${value(s.gold_medals)} <em>/ ${value(goldTarget)}</em></strong><small>الهدف يتدرّج مع الصلوات التي دخل وقتها اليوم</small></div><div class="medal-total silver"><span>الميداليات الفضية</span><strong aria-label="الميداليات الفضية: ${value(s.silver_medals)} من ${value(silverTarget)}">🥈 ${value(s.silver_medals)} <em>/ ${value(silverTarget)}</em></strong><small>الهدف يتدرّج مع السنن المتاحة اليوم</small></div><div><span>صلوات مسجّلة</span><strong>${value(s.completed)} <em>/ ${value(prayerTarget)}</em></strong><small>في ${number(s.recorded_days)} أيام مسجّلة</small></div><div><span>في البيت</span><strong>${value(s.home)}</strong><small>خطوات جميلة</small></div><div><span>في المسجد</span><strong>${value(s.mosque)}</strong><small>خطوات جميلة</small></div><div><span>ركعات السنن</span><strong>${value(s.sunnah_rakahs)}</strong><small>والوتر في ${number(s.witr_days)} أيام</small></div></section><section class="badges-grid" aria-label="إنجازات ${range.label}">${s.achievements.map((a,i)=>`<article class="achievement-badge ${a.unlocked?'unlocked':'future'}"><span class="badge-art" aria-hidden="true">${['🌱','🌟','🏆','🌷'][i%4]}</span><div><span class="badge-status">${a.unlocked?'خطوة وصلت لها ✓':'خطوة قادمة'}</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p></div></article>`).join('')}</section><section class="history-card"><div class="section-heading"><h3>من دفتر أيامك</h3><span>${range.label}</span></div>${state.history.length?`${compactPrayerTable([...state.history].reverse().map(day=>({day,label:`<button type="button" class="text-button" data-action="history-date" data-date="${esc(day.date)}" aria-label="افتح سجل ${esc(reportDateLabel(day.date))}">${esc(new Intl.DateTimeFormat('ar',{weekday:'short',day:'numeric',month:'long'}).format(new Date(day.date+'T12:00:00')))}</button>`})),{label:'اليوم',caption:`من دفتر أيامك — ${range.label}`,region:'جدول سجل الأيام'})}`:'<div class="empty-history"><span aria-hidden="true">✦</span><p>لا توجد خطوات محفوظة في ${range.label}</p><button type="button" class="primary-button compact" data-action="view" data-view="day">إلى صلاتي اليوم</button></div>'}</section><p class="gentle-note">تتحدّث الميداليات والإنجازات مع الفترة المختارة وسجلك المحفوظ</p></main>`;
}
function account(){const options=state.cities.map(city=>`<option value="${esc(city.id)}" ${String(city.id)===String(state.user.city_id)?'selected':''}>${esc(city.name)}</option>`).join('');return `<main id="main" class="page-main account-page"><div class="page-title"><span class="small-chip">مساحتك الصغيرة</span><h2>حسابي</h2></div><section class="account-card"><img src="/assets/child-home.png" alt=""/><h3>${esc(state.user.alias)}</h3><span class="small-chip">اسم مستعار</span><p>صلواتك وسننك محفوظة في حسابك، ويمكنك العودة لأي يوم من دفتر الأيام</p><form id="city-form" class="city-form"><label for="city">مدينتي لحساب مواقيت الصلاة</label><div class="city-fields"><select id="city" name="city_id" required ${state.busy||!state.citiesLoaded?'disabled':''}><option value="">${state.citiesLoaded?'اختر المدينة':'نحمّل المدن…'}</option>${options}</select><button type="submit" class="primary-button compact" ${state.busy||!state.citiesLoaded?'disabled':''}>حفظ المدينة</button></div><small>${state.user.city_name?`المواقيت الحالية حسب ${esc(state.user.city_name)} (${esc(state.user.timezone)})`:'اختر مدينة لتظهر المواقيت وتُفتح الصلوات في وقتها'}</small></form><div class="account-privacy"><h4>خصوصيتك مهمة</h4><p>نحفظ المدينة التي تختارها لحساب مواقيت الصلاة والتاريخ المحلي. لا نطلب إذن الموقع الدقيق أو اسمًا حقيقيًا أو عمرًا</p><p>مصدر المواقيت وطريقة الحساب: <a href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener noreferrer">واجهة AlAdhan لمواقيت الصلاة</a>. قد تختلف المواقيت المحلية دقائق قليلة، فارجع إلى مسجدك المحلي عند الحاجة</p><p>هذه نسخة تطوير تجريبية. استخدم بيانات وهمية فقط. تجهيز نسخة للأطفال يتطلّب مراجعة وليّ الأمر والخصوصية والاستضافة أولًا</p></div><button type="button" class="outline-button" data-action="logout" ${state.busy?'disabled':''}>تسجيل الخروج</button></section>${supervision()}</main>`;}
function inviteCreatedAt(value){const date=new Date(typeof value==='number'?value*1000:value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('ar-SA',{dateStyle:'medium',timeStyle:'short',timeZone:state.user?.timezone||undefined}).format(date);}
function supervision(){return `<section class="supervision-card"><h3>المشرفون على دفتري</h3><p>يمكن لكل مشرف قراءة سجلك السابق واللاحق وإنجازاتك. يمكنك إزالة أي مشرف.</p>${state.managementError?`<p class="form-error" role="alert">${esc(state.managementError)}</p>`:''}${!state.managementLoaded?'<p role="status">نحمّل علاقات الإشراف…</p>':state.supervisors.length?`<ul class="relationship-list">${state.supervisors.map(s=>`<li><span>${esc(s.alias)}</span><button type="button" class="outline-button" data-action="remove-supervisor" data-id="${esc(s.id)}" ${state.busy?'disabled':''}>إزالة المشرف</button></li>`).join('')}</ul>`:'<p>لا يوجد مشرفون على دفتري.</p>'}<button type="button" class="text-button" data-action="refresh-management" ${state.busy?'disabled':''}>تحديث القائمة</button>${state.user.can_supervise?`<h3>رابط الإشراف</h3><p>أرسل نفس الرابط لجميع الأبناء أو الطلاب. كل طفل يؤكد الإضافة بنفسه. إلغاء الرابط أو استبداله لا يزيل العلاقات الحالية.</p>${state.shareLink?`<label for="share-link">رابطك — احتفظ به لنسخه لاحقًا</label><input id="share-link" class="share-link" readonly dir="ltr" value="${esc(state.shareLink)}"/><button type="button" class="outline-button" data-action="copy-invite">نسخ الرابط</button>`:'<p>الرمز يظهر مرة واحدة عند إنشاء الرابط. إذا فقدته، استبدل الرابط لتوليد رابط جديد.</p>'}<div class="supervision-actions"><button type="button" class="primary-button compact" data-action="create-invite" ${state.busy||state.invites.some(i=>!i.revoked_at)?'disabled':''}>إنشاء رابط</button><button type="button" class="outline-button" data-action="rotate-invite" ${state.busy?'disabled':''}>استبدال الرابط</button></div><ul class="relationship-list">${state.invites.map(i=>`<li><span>رابط ${i.revoked_at?'ملغى':'نشط'} · ${esc(inviteCreatedAt(i.created_at))}</span>${!i.revoked_at?`<button type="button" class="outline-button" data-action="revoke-invite" data-id="${esc(i.id)}" ${state.busy?'disabled':''}>إلغاء الرابط</button>`:''}</li>`).join('')}</ul><h3>الأطفال الذين أشرف عليهم</h3><button type="button" class="primary-button compact" data-action="view" data-view="report">متابعة الطلاب · السجل اليومي</button>${state.children.length?`<ul class="relationship-list">${state.children.map(child=>`<li><span>${esc(child.alias)}${child.city_name?` · ${esc(child.city_name)}`:''}</span><div><button type="button" class="primary-button compact" data-action="select-child" data-id="${esc(child.id)}">عرض الدفتر</button><button type="button" class="outline-button" data-action="remove-child" data-id="${esc(child.id)}" ${state.busy?'disabled':''}>إنهاء الإشراف</button></div></li>`).join('')}</ul>`:'<p>لا يوجد أطفال مرتبطون بعد.</p>'}`:`<h3>متابعة الأطفال</h3><p>يمكنك تفعيل الإشراف مع الاحتفاظ بدفتر صلاتك.</p><button type="button" class="primary-button compact" data-action="enable-supervision" ${state.busy?'disabled':''}>تفعيل الإشراف</button>`}</section>`;}
function inviteScreen(){return `<main id="main" class="page-main"><section class="supervision-card invite-card"><h2>إضافة مشرف</h2>${state.invitePreview?`<h3>${esc(state.invitePreview.supervisor.alias)}</h3><p>بقبولك، يستطيع هذا المشرف الاطلاع على أيام صلاتك وسجلك السابق واللاحق وإنجازاتك للقراءة فقط. يمكنك إزالة الإشراف من حسابي في أي وقت.</p><button type="button" class="primary-button compact" data-action="accept-invite" ${state.busy?'disabled':''}>إضافة المشرف</button>`:`<p>نعرض اسم المشرف وصلاحياته قبل تأكيد الإضافة.</p><button type="button" class="primary-button compact" data-action="preview-invite" ${state.busy?'disabled':''}>${state.busy?'نحمّل الدعوة…':'عرض الدعوة'}</button>`}${state.inviteError?`<p class="form-error" role="alert">${esc(state.inviteError)}</p>`:''}<button type="button" class="outline-button" data-action="cancel-invite">إلغاء</button></section></main>`;}
function childBanner(){return state.selectedChild?`<section class="child-context" aria-label="دفتر الطفل المختار"><div><strong>دفتر ${esc(state.selectedChild.alias)} — للقراءة فقط</strong><p>${esc(state.selectedChild.city_name||'لم تُحدّد المدينة')} ${esc(state.selectedChild.timezone||'')}</p></div>${state.reportReturn?'<button type="button" class="outline-button" data-action="view" data-view="report">العودة إلى سجل الطلاب</button>':''}<button type="button" class="outline-button" data-action="own-diary">العودة إلى دفتري</button><button type="button" class="outline-button" data-action="remove-child" data-id="${esc(state.selectedChild.id)}" ${state.busy?'disabled':''}>إنهاء الإشراف</button></section>`:'';}
const reportToday=()=>dateInTimezone(state.user?.timezone);
const reportZone=()=>state.user?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'توقيت الجهاز';
const reportDateLabel=date=>new Intl.DateTimeFormat('ar',{calendar:'gregory',weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(new Date(`${date}T12:00:00`));
function reportCell(day,prayer,value,sunnah=false,witr=false,label=''){
 const eligible=day.schedule&&Object.hasOwn(day.schedule,'eligible_prayers')?day.schedule.eligible_prayers:eligiblePrayerKeys(day);
 const unknown=eligible===null;
 const due=unknown||eligible.includes(prayer);
 const active=sunnah?Boolean(value):value>0;
 const text=!due?'لم يحن وقتها':sunnah?(active?(witr?'مكتمل':'٢ ركعة'):'غير مسجّل'):(value===2?'في المسجد':value===1?'في البيت':'غير مسجّل');
 const recorded=due&&active;
 const description=`${label}: ${text}${unknown?'، الوقت غير متاح':''}`;
 return `<span class="report-record ${sunnah?'sunnah':'fard'} ${!due?'not-due':active?(sunnah?'silver':'gold'):'unrecorded'}" aria-label="${esc(description)}" title="${esc(description)}"><span class="report-icon" aria-hidden="true">${recorded?(sunnah?'🥈':'🥇'):due?'×':'—'}</span><span class="report-points" aria-hidden="true">${recorded?`+${number(sunnah?1:value===2?27:1)}`:'&nbsp;'}</span></span>`;
}
function reportRow(item){
 const d=item.day,s=d.stats||dailyStats(d),student=item.student;
 const fard=key=>reportCell(d,key,d.prayers[key],false,false,`${PRAYERS.find(p=>p.key===key).name}، الفرض`);
 const sunnah=(key,prayer,label)=>reportCell(d,prayer,d.sunnah[key],true,key==='witr',label);
 const cell=(slots)=>`<td><div class="report-slots" style="--report-slots:${slots.length}">${slots.join('')}</div></td>`;
 const value=v=>v==null?'—':number(v);
 const label=item.label??`<button type="button" class="text-button" data-action="report-child" data-id="${esc(student.id)}">${esc(student.alias)}</button>${!item.has_record?'<small>لا يوجد سجل محفوظ لهذا اليوم</small>':''}<small>${esc(student.timezone||'لم تُحدّد المدينة')}</small>`;
 return `<tr${student?` data-student-id="${esc(student.id)}"`:''}><th scope="row">${label}</th>${cell([sunnah('fajr_before','fajr','سنة الفجر القبلية'),fard('fajr')])}${cell([...(d.dhuhr_before_blocks||[d.sunnah.dhuhr_before>=2,d.sunnah.dhuhr_before===4]).map((v,i)=>reportCell(d,'dhuhr',v,true,false,`سنة الظهر القبلية، المجموعة ${number(i+1)}`)),fard('dhuhr'),sunnah('dhuhr_after','dhuhr','سنة الظهر البعدية')])}${cell([fard('asr')])}${cell([fard('maghrib'),sunnah('maghrib_after','maghrib','سنة المغرب البعدية')])}${cell([fard('isha'),sunnah('isha_after','isha','سنة العشاء البعدية'),sunnah('witr','isha','الوتر')])}<td class="report-total"><span title="إجمالي الفرائض المكتملة"><small>فرض</small><strong>${value(s.completed)} / ${value(s.total)}</strong></span><span title="إجمالي السنن المكتملة"><small>سنن</small><strong>${value(s.silver_medals)} / ${value(s.silver_target??(d.schedule==null?7:null))}</strong></span><span title="إجمالي الميداليات الذهبية" aria-label="الميداليات الذهبية: ${value(s.gold_medals)} من ${value(s.gold_target??(d.schedule==null?DAILY_MEDAL_TARGETS.gold:null))}">🥇 ${value(s.gold_medals)}</span><span title="إجمالي الميداليات الفضية" aria-label="الميداليات الفضية: ${value(s.silver_medals)} من ${value(s.silver_target??(d.schedule==null?DAILY_MEDAL_TARGETS.silver:null))}">🥈 ${value(s.silver_medals)}</span></td></tr>`;
}
function compactPrayerTable(items,{label='الطالب',caption,region='جدول سجل الطلاب'}){
 const headers=[[label],['الفجر',['قبل','فرض']],['الظهر',['قبل ١','قبل ٢','فرض','بعد']],['العصر',['فرض']],['المغرب',['فرض','بعد']],['العشاء',['فرض','بعد','وتر']],['الإجمالي']];
 const header=([name,slots])=>`<th scope="col"><span class="report-heading">${name}</span>${slots?`<div class="report-slot-labels" style="--report-slots:${slots.length}">${slots.map(label=>`<small title="${label==='قبل ١'?'سنة الظهر القبلية، المجموعة ١':label==='قبل ٢'?'سنة الظهر القبلية، المجموعة ٢':label==='قبل'?'السنة القبلية':label==='بعد'?'السنة البعدية':label==='وتر'?'الوتر':'الفرض'}">${label}</small>`).join('')}</div>`:''}</th>`;
 return `<div class="report-scroll" role="region" aria-label="${esc(region)}"><table class="report-table"><colgroup><col class="report-student-col"><col class="report-fajr-col"><col class="report-dhuhr-col"><col class="report-asr-col"><col class="report-maghrib-col"><col class="report-isha-col"><col class="report-total-col"></colgroup><caption>${esc(caption)}</caption><thead><tr>${headers.map(header).join('')}</tr></thead><tbody>${items.map(reportRow).join('')}</tbody></table></div>`;
}
function dailyReport(){
 const date=state.reportDate||shiftDate(reportToday(),-1);
 const controls=`<div class="date-controls"><button type="button" data-action="report-shift" data-days="-1" aria-label="اليوم السابق">→</button><input type="date" id="report-date" value="${date}" max="${reportToday()}" aria-label="اختر يوم سجل الطلاب"/><button type="button" data-action="report-shift" data-days="1" aria-label="اليوم التالي" ${date>=reportToday()?'disabled':''}>←</button><button type="button" data-action="report-yesterday">أمس</button><button type="button" data-action="report-today" ${date===reportToday()?'disabled':''}>اليوم</button><button type="button" data-action="report-refresh">تحديث</button></div>`;
 let body;
 if(state.reportLoading)body='<p class="loading" role="status">نحمّل سجل الطلاب…</p>';
 else if(state.reportError)body=`<p class="form-error" role="alert">${esc(state.reportError)}</p><button type="button" class="outline-button" data-action="report-refresh">إعادة المحاولة</button>`;
 else if(!state.reportTotal)body='<p class="report-empty" role="status">لا يوجد طلاب مرتبطون بحسابك. أضف الطلاب عبر رابط الإشراف من حسابي.</p>';
 else body=`${compactPrayerTable(state.reportRows,{caption:`سجل الطلاب — ${reportDateLabel(date)}`})}<div class="report-pages"><button type="button" class="outline-button" data-action="report-page" data-days="-1" ${state.reportOffset===0?'disabled':''}>الصفحة السابقة</button><span role="status">${number(state.reportOffset+1)}–${number(state.reportOffset+state.reportRows.length)} من ${number(state.reportTotal)} طالب</span><button type="button" class="outline-button" data-action="report-page" data-days="1" ${state.reportOffset+50>=state.reportTotal?'disabled':''}>الصفحة التالية</button></div>`;
 return `<main id="main" class="page-main report-main" dir="rtl"><div class="title-and-date"><div class="page-title"><span class="small-chip">للقراءة فقط</span><h2>سجل الطلاب اليومي</h2><p>${esc(reportDateLabel(date))}</p><small>مرجع التاريخ: ${esc(reportZone())}${state.user?.timezone?'':' · توقيت الجهاز'}</small></div>${controls}</div><p class="report-legend">🥇 البيت ١ · المسجد ٢٧ &nbsp; 🥈 لكل سنة مكتملة · <span class="report-legend-fard">×</span> فرض غير مسجّل · <span class="report-legend-sunnah">×</span> سنة غير مسجّلة · غير مسجّل لا يعني تفويت الصلاة</p><p class="muted">الترتيب: الفرائض المكتملة من الأعلى إلى الأقل، ثم السنن المكتملة. إجمالي السنن يحسب المجموعات والوتر، وليس عدد الركعات.</p>${body}</main>`;
}
async function loadDailyReport(){
 if(!state.user?.can_supervise||state.view!=='report')return;
 const stamp=contextStamp(),epoch=++state.reportEpoch,date=state.reportDate,offset=state.reportOffset;
 const current=()=>sameContext(stamp)&&epoch===state.reportEpoch&&state.view==='report'&&date===state.reportDate&&offset===state.reportOffset;
 state.reportRows=[];state.reportLoading=true;state.reportError='';render();
 try{const result=await api(`/supervisor/daily-review?date=${date}&limit=50&offset=${offset}`);if(!current())return;if(offset&&offset>=result.total_students){state.reportOffset=Math.max(0,Math.floor((result.total_students-1)/50)*50);await loadDailyReport();return;}state.reportRows=result.rows;state.reportTotal=result.total_students;}
 catch(error){if(!current())return;state.reportError=error.message;if(error.status===401)handleError(error);}
 finally{if(current()){state.reportLoading=false;render();}}
}
async function changeReportDate(date){if(!validDate(date)||date>reportToday())return;state.reportDate=date;state.reportOffset=0;history.pushState(null,'',`?date=${date}#report`);await loadDailyReport();}
async function reportChild(id){const item=state.reportRows.find(r=>String(r.student.id)===String(id));if(!item)return;state.reportEpoch++;state.selectedChild=item.student;clearData();state.reportReturn=true;state.operationEpoch++;state.busy=false;state.date=state.reportDate;await changeView('day');}
function render(focusKey){root.innerHTML=state.user?`${hero()}${state.inviteToken?inviteScreen():`${childBanner()}${state.view==='report'?dailyReport():state.view==='day'?daily():state.view==='achievements'?achievements():account()}`}${navbar()}`:auth();if(focusKey){const button=root.querySelector(focusKey);button?.focus({preventScroll:true});}}
async function loadDay(date=state.date){const stamp=contextStamp();try{const day=await api(readPath(`/days/${date}`));if(sameContext(stamp)&&date===state.date&&(!state.day||state.day.date!==date||day.version>=state.day.version))state.day=day;}catch(error){if(sameContext(stamp)&&date===state.date)throw error;}}
async function loadManagement(){const stamp=contextStamp(),requestEpoch=++state.managementRequestEpoch;try{const [supervisors,children,invites]=await Promise.all([api('/account/supervisors'),state.user.can_supervise?api('/supervisor/children'):Promise.resolve({children:[]}),state.user.can_supervise?api('/supervisor/invites'):Promise.resolve({invites:[]})]);if(!sameContext(stamp)||requestEpoch!==state.managementRequestEpoch)return;state.supervisors=supervisors.supervisors;state.children=children.children;state.invites=invites.invites;if(state.shareInviteId&&!state.invites.some(i=>String(i.id)===String(state.shareInviteId)&&!i.revoked_at)){state.shareLink='';state.shareInviteId=null;}state.managementLoaded=true;state.managementError='';if(state.selectedChild&&!state.children.some(c=>String(c.id)===String(state.selectedChild.id))){state.selectedChild=null;clearData();}}catch(error){if(sameContext(stamp)&&requestEpoch===state.managementRequestEpoch){state.managementError=error.message;handleError(error);}}}
async function previewInvite(){if(!state.inviteToken||state.busy)return;const operation=++state.operationEpoch;const stamp=contextStamp(),token=state.inviteToken;state.busy=true;state.inviteError='';render();try{const result=await api('/supervisor-invites/preview',{method:'POST',body:JSON.stringify({token})});if(sameContext(stamp)&&token===state.inviteToken)state.invitePreview=result;}catch(error){if(sameContext(stamp)&&token===state.inviteToken){state.inviteError=error.message;if(error.status===401)handleError(error);}}finally{if(operation===state.operationEpoch&&sameContext(stamp)){state.busy=false;render();}}}
async function supervisionAction(action,id){if(state.busy)return;const operation=++state.operationEpoch;const stamp=contextStamp();state.busy=true;state.managementError='';render();try{let result;if(action==='enable-supervision'){result=await api('/account',{method:'PATCH',body:JSON.stringify({can_supervise:true})});if(!sameContext(stamp))return;state.user=result.user||result;}else if(action==='create-invite'||action==='rotate-invite'){result=await api(action==='create-invite'?'/supervisor/invites':'/supervisor/invites/rotate',{method:'POST'});if(!sameContext(stamp))return;state.shareLink=result.link||`${location.origin}/#invite=${encodeURIComponent(result.token)}`;state.shareInviteId=result.invite.id;}else{const path=action==='revoke-invite'?`/supervisor/invites/${encodeURIComponent(id)}`:action==='remove-supervisor'?`/account/supervisors/${encodeURIComponent(id)}`:`/supervisor/children/${encodeURIComponent(id)}`;await api(path,{method:'DELETE'});if(!sameContext(stamp))return;if(action==='revoke-invite'&&String(state.shareInviteId)===String(id)){state.shareLink='';state.shareInviteId=null;}if(action==='remove-child'&&String(state.selectedChild?.id)===String(id)){state.selectedChild=null;clearData();state.view='account';state.date=today();}}state.reportEpoch++;state.reportRows=[];state.reportLoading=false;state.reportTotal=0;await loadManagement();if(state.view==='report'&&state.user?.can_supervise){state.reportOffset=0;await loadDailyReport();}}catch(error){if(sameContext(stamp)){state.managementError=error.message;handleError(error);}}finally{if(operation===state.operationEpoch){state.busy=false;render();}}}
async function selectChild(id){const child=state.children.find(c=>String(c.id)===String(id));if(!child)return;state.selectedChild=child;clearData();state.operationEpoch++;state.busy=false;state.date=today();await changeView('day');}
async function acceptInvite(){if(state.busy||!state.invitePreview)return;const operation=++state.operationEpoch;const stamp=contextStamp(),token=state.inviteToken;try{const saved=JSON.parse(sessionStorage.getItem(INVITE_STORAGE+'.accept')||'null');if(saved?.userId===state.user.id&&saved?.token===token)state.acceptKey=saved.key;}catch{}state.acceptKey??=requestKey();try{sessionStorage.setItem(INVITE_STORAGE+'.accept',JSON.stringify({userId:state.user.id,token,key:state.acceptKey}));}catch{}state.busy=true;state.inviteError='';render();try{await api('/supervisor-invites/accept',{method:'POST',body:JSON.stringify({token,request_key:state.acceptKey})});if(!sameContext(stamp)||token!==state.inviteToken)return;saveInvite('');state.invitePreview=null;state.acceptKey=null;state.view='account';await Promise.all([loadCities(),loadManagement()]);announce('تمت إضافة المشرف');}catch(error){if(sameContext(stamp)&&token===state.inviteToken){state.inviteError=error.message;if(error.status===401)handleError(error);}}finally{if(operation===state.operationEpoch&&sameContext(stamp)){state.busy=false;render();}}}
async function loadCities(){if(state.citiesLoaded)return;const stamp=contextStamp();try{const result=await api('/cities');if(sameContext(stamp)){state.cities=Array.isArray(result.cities)?result.cities:[];state.citiesLoaded=true;}}catch(error){if(sameContext(stamp))throw error;}}
async function loadAchievements(period=state.achievementPeriod){const stamp=contextStamp();const range=achievementRange(period,today());const userId=state.user?.id;const sessionEpoch=state.sessionEpoch;const dataEpoch=state.dataEpoch;const requestEpoch=++state.achievementRequestEpoch;try{const query=`from=${range.from}&to=${range.to}`;const [stats,history]=await Promise.all([api(readPath(`/statistics?${query}`)),api(readPath(`/history?${query}`))]);if(sameContext(stamp)&&state.view==='achievements'&&period===state.achievementPeriod&&requestEpoch===state.achievementRequestEpoch&&userId===state.user?.id&&sessionEpoch===state.sessionEpoch&&dataEpoch===state.dataEpoch){state.stats=stats;state.history=history.days;lastAchievementRefresh=Date.now();return true;}}catch(error){if(sameContext(stamp)&&state.view==='achievements'&&period===state.achievementPeriod&&requestEpoch===state.achievementRequestEpoch&&userId===state.user?.id&&sessionEpoch===state.sessionEpoch)throw error;}return false;}
async function changeAchievementPeriod(period){if(!ACHIEVEMENT_PERIODS[period]||period===state.achievementPeriod)return;state.achievementPeriod=period;state.stats=null;state.history=[];render();try{await loadAchievements(period);render();}catch(error){handleError(error);}}
async function changeView(view){if(!['day','achievements','account','report'].includes(view)||view==='report'&&!state.user?.can_supervise)return;if(state.view==='report'&&view!=='report'){state.reportEpoch++;state.reportRows=[];}if(view==='report'){if(state.selectedChild){state.selectedChild=null;clearData();state.operationEpoch++;state.busy=false;}state.reportDate??=shiftDate(reportToday(),-1);state.reportDate=state.reportDate>reportToday()?reportToday():state.reportDate;state.reportReturn=false;}if(view==='account'&&state.selectedChild){state.selectedChild=null;clearData();state.operationEpoch++;state.busy=false;state.date=today();}state.view=view;state.error='';if(location.hash!==`#${view}`)history.pushState(null,'',`?date=${view==='report'?state.reportDate:state.date}#${view}`);render();try{if(view==='day'&&!state.day)await loadDay();if(view==='achievements')await loadAchievements();if(view==='account')await Promise.all([loadCities(),loadManagement()]);if(view==='report')await loadDailyReport();render();}catch(error){handleError(error);}}
async function changeDate(date){if(!validDate(date))return;state.date=date;state.day=null;state.view='day';history.pushState(null,'',`?date=${date}#day`);render();try{await loadDay(date);render();}catch(error){handleError(error);}}
function handleError(error){if(error.status===401){state.user=null;state.sessionEpoch++;resetAccount();state.error='انتهت جلسة الدخول. افتح دفترك مرة أخرى';render();}else {if(state.selectedChild&&(error.status===403||error.status===404)){state.selectedChild=null;clearData();state.view='account';state.managementError=error.message;loadManagement().then(()=>render());render();}announce(error.message,true);}}
async function mutate(path,payload,focusKey){
 if(state.busy||!state.day||state.selectedChild)return;
 const stamp=contextStamp();const date=state.date,userId=state.user?.id,sessionEpoch=state.sessionEpoch,version=state.day.version,view=state.view;
 state.busy=true;render(focusKey);
 try{
  const day=await api(path,{method:path.endsWith('/cycle')?'POST':'PATCH',body:JSON.stringify({...payload,version})});
  if(sameContext(stamp)&&userId===state.user?.id&&sessionEpoch===state.sessionEpoch){
   state.dataEpoch++;state.stats=null;
   if(date===state.date&&(!state.day||state.day.date!==date||day.version>=state.day.version))state.day=day;
   if(state.view==='achievements')await loadAchievements();
  }
 }catch(error){
  if(!sameContext(stamp))return;
  if(error.status===409){await loadDay(date);if(sameContext(stamp)&&date===state.date)announce('تحدّث الدفتر من نافذة أخرى. جرّب الخطوة مرة أخرى',true);}
  else handleError(error);
 }finally{
  if(sameContext(stamp)){state.busy=false;render(date===state.date&&view===state.view?focusKey:undefined);}
 }
}
root.addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button||button.disabled)return;const {action,key,block,view,date,days,mode,period,id}=button.dataset;
 if(action==='report-shift'){await changeReportDate(shiftDate(state.reportDate,Number(days)));return;}
 if(action==='report-yesterday'||action==='report-today'){await changeReportDate(action==='report-today'?reportToday():shiftDate(reportToday(),-1));return;}
 if(action==='report-refresh'){state.reportOffset=0;await loadDailyReport();return;}
 if(action==='report-page'){state.reportOffset=Math.max(0,state.reportOffset+Number(days)*50);await loadDailyReport();return;}
 if(action==='report-child'){await reportChild(id);return;}
 if(action==='cancel-invite'){state.operationEpoch++;saveInvite('');state.invitePreview=null;state.inviteError='';state.acceptKey=null;state.busy=false;render();return;}
 if(action==='preview-invite'){await previewInvite();return;}
 if(action==='accept-invite'){await acceptInvite();return;}
 if(['enable-supervision','create-invite','rotate-invite','revoke-invite','remove-supervisor','remove-child'].includes(action)){await supervisionAction(action,id);return;}
 if(action==='refresh-management'){await loadManagement();render();return;}
 if(action==='select-child'){await selectChild(id);return;}
 if(action==='own-diary'){state.reportReturn=false;state.selectedChild=null;clearData();state.operationEpoch++;state.busy=false;state.date=today();await changeView('day');return;}
 if(action==='copy-invite'){const stamp=contextStamp(),link=state.shareLink;try{if(!globalThis.navigator?.clipboard?.writeText)throw new Error('clipboard');await globalThis.navigator.clipboard.writeText(link);if(sameContext(stamp))announce('نُسخ الرابط');}catch{if(sameContext(stamp)){const field=root.querySelector('#share-link');field?.focus();field?.select?.();announce('تعذّر النسخ التلقائي. حدّد الرابط وانسخه يدويًا',true);}}return;}
 if(action==='auth-mode'){state.authMode=mode;state.error='';render();root.querySelector('#alias')?.focus();}
 else if(action==='view')await changeView(view);
 else if(action==='date-shift')await changeDate(shiftDate(state.date,Number(days)));
 else if(action==='today')await changeDate(today());
 else if(action==='history-date')await changeDate(date);
 else if(action==='achievement-period')await changeAchievementPeriod(period);
 else if(action==='prayer'&&prayerEnabled(key))await mutate(`/days/${state.date}/prayers/${key}/cycle`,{},`[data-action="prayer"][data-key="${key}"]`);
 else if(action==='sunnah'){const prayerKey=key.split('_')[0];if(!prayerEnabled(prayerKey))return;const isDhuhr=key==='dhuhr_before';const value=isDhuhr?!state.day.dhuhr_before_blocks[Number(block)]:state.day.sunnah[key]?0:2;await mutate(`/days/${state.date}/sunnah`,{key,value,...(isDhuhr?{block:Number(block)}:{})},`[data-action="sunnah"][data-key="${key}"]${isDhuhr?`[data-block="${block}"]`:''}`);}
 else if(action==='witr'&&prayerEnabled('isha'))await mutate(`/days/${state.date}/sunnah`,{key:'witr',value:!state.day.sunnah.witr},'[data-action="witr"]');
 else if(action==='logout'){if(authRequestPending)return;authRequestPending=true;const userId=state.user?.id,sessionEpoch=state.sessionEpoch;state.busy=true;render();try{await api('/auth/logout',{method:'POST'});if(userId!==state.user?.id||sessionEpoch!==state.sessionEpoch)return;state.user=null;state.sessionEpoch++;resetAccount();state.authMode='login';state.error='';history.replaceState(null,'',location.pathname);}catch(error){if(userId===state.user?.id&&sessionEpoch===state.sessionEpoch)handleError(error);}finally{authRequestPending=false;state.busy=false;render();}}
});
root.addEventListener('change',event=>{if(event.target.id==='day-date')changeDate(event.target.value);if(event.target.id==='report-date')changeReportDate(event.target.value);});
root.addEventListener('submit',async event=>{event.preventDefault();if(state.busy||authRequestPending)return;if(event.target.id==='city-form'){const form=new FormData(event.target);const cityId=String(form.get('city_id')||'');if(!cityId)return;let stamp=contextStamp();const operation=++state.operationEpoch;state.busy=true;render();try{const result=await api('/account',{method:'PATCH',body:JSON.stringify({city_id:cityId})});if(!sameContext(stamp))return;state.user=result.user||result;clearData();stamp=contextStamp();state.date=today();await loadDay();if(state.view==='achievements')await loadAchievements();history.replaceState(null,'',`?date=${state.date}#${state.view}`);announce('حُفظت مدينتك وتحدّثت المواقيت ✦');}catch(error){if(sameContext(stamp))handleError(error);}finally{if(operation===state.operationEpoch&&sameContext(stamp)){state.busy=false;render();}}return;}if(event.target.id!=='auth-form')return;
 const form=new FormData(event.target),alias=String(form.get('alias')).trim(),password=String(form.get('password')),mode=state.authMode;
 const sessionEpoch=state.sessionEpoch;let operation=++state.operationEpoch;
 authRequestPending=true;state.busy=true;state.error='';const submit=event.target.querySelector('[type=submit]');submit.disabled=true;submit.textContent='لحظة صغيرة…';
 try{
  const result=await api(`/auth/${mode}`,{method:'POST',body:JSON.stringify({alias,password,...(mode==='register'?{account_type:form.get('account_type')||'child'}:{})})});
  if(sessionEpoch!==state.sessionEpoch)return;
  state.user=result.user;state.sessionEpoch++;resetAccount();operation=state.operationEpoch;state.busy=true;state.date=today();state.view='day';
  const stamp=contextStamp();
  try{await loadDay();}catch(error){if(sameContext(stamp))handleError(error);}
  if(!sameContext(stamp))return;
  state.busy=false;history.replaceState(null,'',`?date=${state.date}#day`);
  if(state.inviteToken){await previewInvite();operation=state.operationEpoch;}
  if(sameContext(stamp))announce(state.user.city_id?'أهلاً بك في دفتر يومك ✦':'أهلاً بك ✦ اختر مدينتك من حسابي لعرض المواقيت');
 }catch(error){if(sessionEpoch===state.sessionEpoch)state.error=error.message;}
 finally{authRequestPending=false;if(operation===state.operationEpoch){state.busy=false;render();if(!state.user){root.querySelector('#alias').value=alias;root.querySelector('#password')?.focus();}}}
});
window.addEventListener('hashchange',async()=>{if(captureInvite()){render();if(state.user)await previewInvite();}});
window.addEventListener('popstate',async()=>{if(captureInvite()){render();if(state.user)await previewInvite();return;}if(!state.user)return;const date=validDate(new URLSearchParams(location.search).get('date'))||today();if(date!==state.date){state.date=date;state.day=null;}state.view=['day','achievements','account',...(state.user?.can_supervise?['report']:[])].includes(location.hash.slice(1))?location.hash.slice(1):'day';if(state.view==='account'&&state.selectedChild){state.selectedChild=null;clearData();state.operationEpoch++;state.busy=false;state.date=today();}render();try{if(state.view==='day'&&!state.day)await loadDay();if(state.view==='achievements')await loadAchievements();if(state.view==='account')await Promise.all([loadCities(),loadManagement()]);if(state.view==='report'){state.selectedChild=null;clearData();state.reportDate=validDate(new URLSearchParams(location.search).get('date'))||shiftDate(reportToday(),-1);if(state.reportDate>reportToday())state.reportDate=reportToday();state.reportOffset=0;await loadDailyReport();}render();}catch(error){handleError(error);}});
async function init(){
 const sessionEpoch=state.sessionEpoch;let stamp=null;
 try{
  const result=await api('/auth/me');
  if(authRequestPending||sessionEpoch!==state.sessionEpoch)return;
  state.user=result.user;state.sessionEpoch++;resetAccount();stamp=contextStamp();
  const requested=validDate(new URLSearchParams(location.search).get('date'));state.date=requested||today();
  state.view=['day','achievements','account',...(state.user?.can_supervise?['report']:[])].includes(location.hash.slice(1))?location.hash.slice(1):'day';
  await loadDay();if(!sameContext(stamp))return;
  if(state.view==='achievements')await loadAchievements();
  if(state.view==='account')await Promise.all([loadCities(),loadManagement()]);if(state.view==='report'){state.selectedChild=null;clearData();state.reportDate=validDate(new URLSearchParams(location.search).get('date'))||shiftDate(reportToday(),-1);if(state.reportDate>reportToday())state.reportDate=reportToday();state.reportOffset=0;await loadDailyReport();}
 }catch(error){
  if(!authRequestPending&&(stamp?sameContext(stamp):sessionEpoch===state.sessionEpoch)&&error.status!==401)state.error='تعذّر فتح الدفتر. تأكّد أن الخادم يعمل، ثم أعد المحاولة';
 }finally{state.loading=false;render();}
 if(state.user&&state.inviteToken&&!authRequestPending)await previewInvite();
}
let lastEligibility='';let lastScheduleRetry=0;let lastAchievementRefresh=0;let scheduleRefreshBusy=false;
async function scheduleTick(){if(state.view==='report'||!state.user||!state.day)return;const cityToday=today();if(state.day.schedule?.today&&state.day.schedule.today!==cityToday){if(state.date===state.day.schedule.today){await changeDate(cityToday);return;}try{await loadDay(state.date);if(state.view==='day')render();}catch{}return;}const signature=JSON.stringify(scheduleKeys());const eligibilityChanged=signature!==lastEligibility;if(eligibilityChanged){lastEligibility=signature;if(state.view==='day')render();}if(state.view==='achievements'&&!scheduleRefreshBusy&&(eligibilityChanged||Date.now()-lastAchievementRefresh>=60000)){scheduleRefreshBusy=true;try{await loadAchievements();render();}catch(error){handleError(error);}finally{scheduleRefreshBusy=false;}}if(scheduleUnavailable()&&Date.now()-lastScheduleRetry>300000){lastScheduleRetry=Date.now();try{await loadDay();if(state.view==='day')render();}catch{}}}
const scheduleTimer=typeof window.setInterval==='function'?window.setInterval(()=>scheduleTick().catch(()=>{}),30000):null;scheduleTimer?.unref?.();
init();
